set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000001","session_id":"00000000-0000-0000-0000-000000000001"}',true);
select public.switch_learner_enrollment('cbse-8-mathematics','English');
select public.switch_learner_enrollment('cbse-6-mathematics','English');
select public.switch_learner_enrollment('cbse-8-mathematics','English');
select pg_temp.assert_true((select count(*)=1 from public.learner_academic_enrollments where is_active),'one active context after switches');
select pg_temp.assert_true((select count(*)=2 from public.learner_academic_enrollments),'context history retained');
select pg_temp.expect_error($q$select public.switch_learner_enrollment('missing','English')$q$,'22023','missing academic path denied');
select pg_temp.expect_error($q$select public.switch_learner_enrollment('cbse-8-mathematics','हिन्दी')$q$,'22023','unavailable catalog language denied');
select pg_temp.assert_true((select subject_id='cbse-8-mathematics' from public.learner_academic_enrollments where is_active),'invalid switch retains current context');
select pg_temp.expect_error($q$update public.learner_academic_enrollments set is_active=false$q$,'42501','direct switch bypass denied');
select public.record_learner_reading('equations',false);
select pg_temp.assert_true((select read_at is null from public.learner_lesson_activity where lesson_id='equations'),'opening is started, not read');
select public.record_learner_reading('equations',true);
select public.record_learner_reading('equations',true);
select public.record_learner_reading('equations',false);
select pg_temp.assert_true((select count(*)=1 and bool_and(read_at is not null and read_at>=started_at) from public.learner_lesson_activity),'reading idempotent and monotonic');
select pg_temp.assert_true((select checkpoint_percent=25 from public.lesson_progress where lesson_id='equations'),'reading never awards mastery');
select pg_temp.expect_error($q$insert into public.learner_lesson_activity(learner_id,lesson_id,read_at) values(auth.uid(),'water',now())$q$,'42501','client cannot forge reading timestamps or ownership');
select pg_temp.expect_error($q$update public.learner_lesson_activity set read_at=now()$q$,'42501','direct reading writes denied');
select pg_temp.expect_error($q$select public.record_learner_reading('missing',true)$q$,'22023','missing resource denied');
reset role;
update public.academic_grades set is_published=false where id='cbse-8';
set local role authenticated;
select pg_temp.expect_error($q$select public.record_learner_reading('equations',true)$q$,'22023','unpublished ancestor blocks reading');
select pg_temp.expect_error($q$select public.switch_learner_enrollment('cbse-8-mathematics','English')$q$,'22023','unpublished context denied');
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000002","session_id":"00000000-0000-0000-0000-000000000002"}',true);
select pg_temp.assert_true((select count(*)=0 from public.learner_lesson_activity),'cross-user activity hidden');
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000003","session_id":"00000000-0000-0000-0000-000000000003"}',true);
select pg_temp.expect_error($q$select public.record_learner_reading('water',true)$q$,'42501','tutor cannot record learner activity');
select pg_temp.expect_error($q$select public.switch_learner_enrollment('cbse-6-mathematics','English')$q$,'42501','tutor cannot enrol as learner');
reset role;
delete from auth.sessions where id='00000000-0000-0000-0000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000001","session_id":"00000000-0000-0000-0000-000000000001"}',true);
select pg_temp.assert_true((select count(*)=0 from public.learner_lesson_activity),'revoked session cannot read activity');
select pg_temp.expect_error($q$select public.record_learner_reading('water',true)$q$,'42501','revoked session cannot record activity');
select pg_temp.expect_error($q$select public.switch_learner_enrollment('cbse-6-mathematics','English')$q$,'42501','revoked session cannot switch context');
reset role;
set local role anon;
select pg_temp.expect_error($q$select * from public.learner_lesson_activity$q$,'42501','anonymous activity reads denied');
select pg_temp.expect_error($q$select public.record_learner_reading('water',true)$q$,'42501','anonymous RPC execution denied');
reset role;
